from base import *
def write():
 t=(R/'journal/business-planner-weekly-review/index.html').read_text();styles=t[t.index('<style>'):t.index('</style>')+8];nav=t[t.index('<header class="nav">'):t.index('</header>')+9];footer=t[t.index('<footer class="site">'):]
 image_inputs=json.loads((D/'image-inputs.json').read_text());manifest=[]
 for a in A:
  slug=a['slug'];src=Path(image_inputs[slug]);asset='/images/journal/'+slug+'-20261107.webp';dest=R/asset.lstrip('/');dest.parent.mkdir(exist_ok=True,parents=True)
  with Image.open(src) as im:
   stream=BytesIO();im.resize((1200,800)).save(stream,'WEBP',quality=83,method=6);data=stream.getvalue();assert len(data)>1000;dest.write_bytes(data)
  url='https://nexalyplanner.com/journal/'+slug+'/'
  schema={'@context':'https://schema.org','@type':'BlogPosting','headline':a['title'],'description':a['desc'],'image':'https://nexalyplanner.com'+asset,'mainEntityOfPage':url,'author':{'@type':'Organization','name':'NexalyPlanner','url':'https://nexalyplanner.com/about/'},'publisher':{'@type':'Organization','name':'NexalyPlanner'},'datePublished':'2026-11-07','dateModified':'2026-11-07','inLanguage':'en-US'}
  head=f'<!doctype html><html lang="en-US"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(a["title"])}</title><meta name="description" content="{E(a["desc"])}"><link rel="canonical" href="{url}"><meta property="og:image" content="https://nexalyplanner.com{asset}"><meta name="twitter:image" content="https://nexalyplanner.com{asset}"><meta property="og:image:alt" content="{E(a["alt"])}"><meta property="og:type" content="article"><meta property="article:published_time" content="2026-11-07"><meta property="article:modified_time" content="2026-11-07">{styles}<style>.reading h2{{scroll-margin-top:110px}}</style><link rel="stylesheet" href="/assets/css/style.css?v=7e6083e6f963"><script type="application/ld+json">{json.dumps(schema)}</script></head><body>'
  page=head+nav+f'<header class="article-hero"><div class="brand">NEXALYPLANNER JOURNAL</div><h1>{E(a["title"])}</h1><p class="metadata">By NexalyPlanner · Published November 7, 2026</p></header><main><p class="toplink"><a href="/journal/">Back to the Journal</a></p><article class="reading"><figure class="article-feature"><img src="{asset}" width="1200" height="800" alt="{E(a["alt"])}" fetchpriority="high" decoding="async"><figcaption>AI-generated editorial illustration matched to this topic. Screens and cards are conceptual; the worked HTML tables contain the exact example figures.</figcaption></figure>'+a['body']+f'<aside class="related-guides"><h2>Continue planning</h2><p><a href="{a["related"]}">View the relevant planner and its documented features</a></p><p><a href="/journal/business-plan-examples/">Compare business plan examples</a></p></aside></article></main>'+footer
  path=R/'journal'/slug/'index.html';path.parent.mkdir(exist_ok=True);path.write_text(page)
  manifest.append({k:a[k] for k in ['slug','title','alt','sources']}|{'asset':asset,'word_count':len(re.sub('<[^>]+>',' ',a['body']).split())})
 (D/'articles.json').write_text(json.dumps(manifest,indent=2));print([(a['slug'],a['word_count']) for a in manifest])
